=== FILE: tick_timer_cov_tb.sv ===
// Coverage testbench for tick_timer.v (RX-E2), extending tick_timer_idle_tb.sv.
// Exercises one-shot and periodic counting, expiry, W1C clear, expiry-over-clear,
// CTRL-write-over-expiry, stop/hold, IE/irq, ignored upper wdata bits, and a
// reset in mid-count, and toggles every stored bit of LOAD and COUNT.
// The bus is driven 1 ns after each rising edge; rdata is combinational.
`timescale 1ns / 1ps
module tick_timer_cov_tb;
    logic        clk = 1'b0;
    logic        rst_n = 1'b0;
    logic        we = 1'b0;
    logic [1:0]  addr = 2'd0;
    logic [31:0] wdata = 32'd0;
    logic [31:0] rdata;
    logic        irq;
    int checks = 0, errors = 0;
    logic [8*64-1:0] nonce;

    tick_timer #(.W(16)) dut (.clk(clk), .rst_n(rst_n), .we(we), .addr(addr), .wdata(wdata), .rdata(rdata), .irq(irq));
    always #5 clk = ~clk;

    task automatic expect_reg(input logic [1:0] a, input logic [31:0] expected);
        addr = a;
        #1;
        checks++;
        if (rdata !== expected) begin
            errors++;
            $display("MISMATCH addr %0d: got %h expected %h at %0t", a, rdata, expected, $time);
        end
    endtask

    task automatic expect_irq(input logic expected);
        checks++;
        if (irq !== expected) begin
            errors++;
            $display("MISMATCH irq: got %b expected %b at %0t", irq, expected, $time);
        end
    endtask

    task automatic bus_write(input logic [1:0] a, input logic [31:0] d);
        we = 1'b1; addr = a; wdata = d;
        @(posedge clk); #1;
        we = 1'b0; wdata = 32'd0;
    endtask

    task automatic cycles(input int n);
        repeat (n) @(posedge clk);
        #1;
    endtask

    initial begin
        // Reset.
        repeat (3) @(posedge clk);
        #1;
        rst_n = 1'b1;
        cycles(1);
        expect_reg(2'd0, 32'd0);
        expect_reg(2'd1, 32'd0);
        expect_reg(2'd2, 32'd0);
        expect_reg(2'd3, 32'd0);
        expect_irq(1'b0);

        // Register access; upper wdata bits are ignored.
        bus_write(2'd0, 32'h0000_0006);
        expect_reg(2'd0, 32'h0000_0006);
        expect_reg(2'd2, 32'd0);
        bus_write(2'd1, 32'hFFFF_FFFF);
        expect_reg(2'd1, 32'h0000_FFFF);
        bus_write(2'd1, 32'h0000_0000);
        expect_reg(2'd1, 32'd0);
        bus_write(2'd0, 32'hFFFF_FFF8);
        expect_reg(2'd0, 32'd0);

        // One-shot: load 3, start, count to zero, expire, stop.
        bus_write(2'd1, 32'd3);
        bus_write(2'd0, 32'h0000_0001);
        expect_reg(2'd2, 32'd3);
        expect_reg(2'd0, 32'h0000_0001);
        cycles(3);
        expect_reg(2'd2, 32'd0);
        expect_reg(2'd3, 32'd0);
        cycles(1);
        expect_reg(2'd3, 32'd1);
        expect_reg(2'd0, 32'd0);
        expect_reg(2'd2, 32'd0);
        expect_irq(1'b0);
        cycles(2);
        expect_reg(2'd2, 32'd0);
        expect_reg(2'd3, 32'd1);

        // IE alone raises irq; writing 0 to STATUS keeps the flag, writing 1 clears it.
        bus_write(2'd0, 32'h0000_0004);
        expect_reg(2'd0, 32'h0000_0004);
        expect_irq(1'b1);
        expect_reg(2'd3, 32'd1);
        bus_write(2'd3, 32'd0);
        expect_reg(2'd3, 32'd1);
        expect_irq(1'b1);
        bus_write(2'd3, 32'd1);
        expect_reg(2'd3, 32'd0);
        expect_irq(1'b0);

        // Periodic: load 2, start with IE.
        bus_write(2'd1, 32'd2);
        bus_write(2'd0, 32'h0000_0007);
        expect_reg(2'd2, 32'd2);
        expect_reg(2'd0, 32'h0000_0007);
        cycles(2);
        expect_reg(2'd2, 32'd0);
        expect_reg(2'd3, 32'd0);
        cycles(1);
        expect_reg(2'd2, 32'd2);
        expect_reg(2'd3, 32'd1);
        expect_irq(1'b1);
        // Clear while running.
        bus_write(2'd3, 32'd1);
        expect_reg(2'd2, 32'd1);
        expect_reg(2'd3, 32'd0);
        expect_irq(1'b0);
        cycles(1);
        expect_reg(2'd2, 32'd0);
        // An expiry wins over a clear at the same edge.
        bus_write(2'd3, 32'd1);
        expect_reg(2'd3, 32'd1);
        expect_reg(2'd2, 32'd2);
        bus_write(2'd3, 32'd1);
        expect_reg(2'd3, 32'd0);
        expect_reg(2'd2, 32'd1);
        cycles(1);
        expect_reg(2'd2, 32'd0);
        // A CTRL write at a zero count takes the expiry's place; no reload while enabled.
        bus_write(2'd0, 32'h0000_0007);
        expect_reg(2'd2, 32'd0);
        expect_reg(2'd3, 32'd0);
        expect_reg(2'd0, 32'h0000_0007);
        cycles(1);
        expect_reg(2'd3, 32'd1);
        expect_reg(2'd2, 32'd2);
        // Stop: the count holds.
        bus_write(2'd0, 32'h0000_0000);
        expect_reg(2'd0, 32'd0);
        expect_reg(2'd2, 32'd2);
        cycles(3);
        expect_reg(2'd2, 32'd2);
        expect_reg(2'd3, 32'd1);
        expect_irq(1'b0);
        bus_write(2'd3, 32'd1);
        expect_reg(2'd3, 32'd0);

        // Full-width count, then reset in mid-count.
        bus_write(2'd1, 32'hFFFF_FFFF);
        bus_write(2'd0, 32'h0000_0001);
        expect_reg(2'd2, 32'h0000_FFFF);
        cycles(1);
        expect_reg(2'd2, 32'h0000_FFFE);
        rst_n = 1'b0;
        cycles(2);
        rst_n = 1'b1;
        cycles(1);
        expect_reg(2'd0, 32'd0);
        expect_reg(2'd1, 32'd0);
        expect_reg(2'd2, 32'd0);
        expect_reg(2'd3, 32'd0);
        expect_irq(1'b0);

        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = "none";
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, (checks > errors ? checks - errors : 0), errors);
        $finish;
    end
endmodule
=== END FILE ===
